def shapevariants(sh):
 # transforms dihedral normalized
 pts=list(sh); trans=[]
 for k in range(8):
  if k<4: q=[(r,c) if k==0 else (c,-r) for r,c in pts] # bug iterative? redefine
 for flip in (False,True):
  for rot in range(4):
   q=[]
   for r,c in pts:
    if flip:c=-c
    for _ in range(rot): r,c=c,-r
    q.append((r,c))
   mr=min(r for r,c in q);mc=min(c for r,c in q)
   trans.append(tuple(sorted((r-mr,c-mc) for r,c in q)))
 return set(trans)

